import dspy

def score_answer(gold, pred, trace, pred_name, pred_trace):
    """傳回分數同畀反饋模型嘅建設性反饋。"""
    expected = gold.answer.strip().lower()
    actual = (pred.answer or "").strip().lower()

    if expected == actual:
        return dspy.Prediction(score=1.0, feedback="答案符合預期輸出。")
    if expected in actual:
        return dspy.Prediction(
            score=0.5,
            feedback=f"部分答案。預期輸出為 {expected}，而實際得到 {actual}。",
        )
    return dspy.Prediction(
        score=0.0,
        feedback=f"答案不相符。預期輸出為 {expected}，而實際得到 {actual}。",
    )

